import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss;

  Transaction({required this.coinName, required this.dateTime, required this.profitLoss});
}

Map<String, double> calculateAverageProfitLoss(List<Transaction> transactions) {
  final profitMap = <String, double>{};
  final lossMap = <String, double>{};

  for (final transaction in transactions) {
    profitMap.update(transaction.coinName, (value) => value + transaction.profitLoss,
        ifAbsent: () => transaction.profitLoss);
    lossMap.update(transaction.coinName, (value) => value - transaction.profitLoss,
        ifAbsent: () => -transaction.profitLoss); // Track loss as negative profit
  }

  // Calculate averages and rank
  final sortedProfits = profitMap.entries.map((entry) => MapEntry(entry.key, entry.value / transactions.where((t) => t.coinName == entry.key).length)).toList()
    ..sort((a, b) => b.value.compareTo(a.value)); // Descending order by average profit
  final sortedLosses = lossMap.entries.map((entry) => MapEntry(entry.key, entry.value / transactions.where((t) => t.coinName == entry.key).length))
    ..sort((a, b) => a.value.compareTo(b.value)); // Ascending order by average loss

  return {
    'topProfits': Map.fromEntries(sortedProfits.sublist(0, 3)),
    'topLosses': Map.fromEntries(sortedLosses.sublist(0, 3))
  };
}

