export const CreateObjectView = observer(({ model }: { model: CreateObjectModel }) => {
  return (
    <div id="create-object-container">  {/* Added container ID */}
      <h2>Select Asset to Create</h2> 
      <select id="asset-dropdown" onChange={(e) => {
        if (e.target.value) {
          model.createObject(e.target.value).then(() => {
            model.setSelectedAsset(e.target.value); 
          });
        }
      }}>
        {model.availableAssets.map((asset, index) => (
          <option key={index} value={asset}> {asset} </option>  {/* Added key and value attributes */}
        ))}
      </select>

      <button id="cleanup-button" onClick={model.cleanupScene}>Cleanup scene</button>  {/* Added button ID */}
    </div>
  )
})
