const axios = require('axios'); // Assuming you've included a library like axios for API calls

/**
 * Posts a message to a specified Slack channel using the Slack API.
 *
 * @param {string} text - The message content to post.
 * @param {string} channelId - The ID of the Slack channel to send the message to.
 * @param {object} [slackApiToken] - An object containing your Slack API token  (e.g., { token: 'YOUR_SLACK_API_TOKEN' })
 * @returns {Promise<object>} A Promise resolving with the Slack API's response data upon successful posting, 
 *                          or an error object otherwise.
 */
async function postToSlack(text, channelId, slackApiToken) {
  if (!slackApiToken || !slackApiToken.token) {
    return Promise.reject(new Error("Missing required Slack API token in 'slackApiToken' object."));
  }

  const apiUrl = 'https://slack.com/api/chat.postMessage'; // Slack API endpoint
  const payload = {
    channel: channelId,
    text: text,
    // Add optional parameters like thread_ts, username, etc. as needed for richer messages
  };

  try {
    const response = await axios.post(apiUrl, payload, {
      headers: {
        Authorization: `Bearer ${slackApiToken.token}` // Authenticate with the token
      }
    });
    return response.data; // Return Slack's API response
  } catch (error) {
    console.error('Slack posting error:', error);
    return Promise.reject(error); // Handle and return errors
  }
}

// Example Usage:
const myChannelId = 'C123ABC45'; // Replace with your actual channel ID
const myToken = { token: 'your_ gerçek_slack_api_token' }; //  Securely store and provide your token

postToSlack('Hello from my JavaScript function!', myChannelId, myToken)
  .then(data => console.log('Message posted successfully:', data))
  .catch(err => console.error('Posting failed:', err));
