import Foundation

func correctHomophones(inputString: String) -> String {
    let homophonePairs: [String: String] = [
        "their": "there",
        "know": "no",
        "weigh": "way",
        "too": "to",
        "yew": "you",
        "sea": "see",
        "sumthing": "something",
        "seams": "seems",
        "bee": "be",
        "eye": "I",
        "knot": "not",
        "right": "write",
        "butt": "but",
        "don't no": "don't know",
        "write weigh": "right way",
        "weather": "whether",
        "there/their/they're":  { context in // Special handling for these
            switch context {
            case "there": return "there"
            case "their": return "their"
            case "they're": return "they're"
            default: return "**contextually ambiguous - preserved**" 
            }
        }
    ]

    var correctedString = inputString
    for (original, replacement) in homophonePairs {
        if let replacementClosure = replacement as? (_ context: String) -> String {
            correctedString = correctedString.replacingOccurrences(of: original, with: replacementClosure(extractContext(original: original, in: correctedString)))
        } else {
            correctedString = correctedString.replacingOccurrences(of: original, with: replacement)
        }
    }
    return correctedString
}

// Helper to extract context for ambiguous replacements (improves accuracy)
func extractContext(original: String, in text: String) -> String {
    let range = text.range(of: original)!
    let surrounding = text[Range(range.lowerBound..<range.upperBound, in: text)!]
    return surrounding // Return surrounding words for better context
}

